"""Source register; inspected passages and access limitations, 4 October 2026."""
ASOF='2026-10-04'
sources, retrievals = [], []
def src(n,title,author,url,published,kind,locator,passage,note='',status='Passage inspected',method='web.run: identified page text / PDF passage inspected',origin=None):
    sid=f'S{n:03d}'
    sources.append({'Source ID':sid,'Title':title,'Author / institution':author,'Publication date':published,'URL':url,'Access date':ASOF,'Source class':kind,'Primary / secondary':'Primary' if kind in ('Official record','Court judgment','Audit','Speech / interview') else 'Secondary','Access status':status,'Origin ID':origin or sid,'Locator':locator,'Reliability / limitation':note or 'Institutional statements establish the reported action or position, not independent causal impact.','Language / geography':'Hindi / India' if n==37 else 'English / India'})
    retrievals.append({'id':f'R{n:03d}','source_id':sid,'url_or_query':url,'access_date':ASOF,'route':'Canonical record or named reproduction','access_status':status,'origin_id':origin or sid,'locator':locator,'passage_paraphrase':passage,'method':method,'result':'Identified passage read' if status=='Passage inspected' else note,'next_action':'Refresh when updating the research; inspect specified primary record where access remains incomplete.'})

src(1,"Who's Who, Rajya Sabha 2020: Scindia",'Rajya Sabha Secretariat','https://cms.rajyasabha.nic.in/UploadedFiles/ElectronicPublications/larrdis/WhosWho_2020.pdf','2020','Official record','PDF pp.459–460 (printed 426–427), Scindia entry','Born 1 January 1971, Mumbai; father Madhavrao, mother Madhavi Raje. BA/MBA; Doon, Harvard and Stanford. Lok Sabha: 2002–04, 2004–09, 2009–14, May 2014–May 2019; Rajya Sabha elected June 2020. Communications/IT MoS 6 April 2008–22 May 2009; Commerce/Industry MoS 28 May 2009–28 October 2012; independent-charge Power MoS 28 October 2012–26 May 2014. Parliamentary committees and Scindia Kanya Vidyalaya association listed.','Historical institutional biography. Personal details are member-supplied. Its precise 2008 ministry date is preferred over a conflicting 2007 year in S005.')
src(2,'Biography of Jyotiraditya M. Scindia','Rajiv Gandhi National Aviation University','https://www.rgnau.ac.in/upload/Bio_JM_Scindia_2.pdf',None,'Official record','One-page biography; education, party and policy paragraphs','Harvard economics BA and Stanford MBA; finance career. Congress chief whip in Lok Sabha from 2014; AICC general secretary for western Uttar Pradesh in 2019; Congress Working Committee service. Biography credits Project Arrow, export facilitation and national-grid integration.','Undated aviation/steel-era institutional profile, not independent evaluation of achievements or a current-office source.')
